                                                                                                                                                                                                       
  CREATE TABLE "CHECK_CHANGE_CONFIG"                                                                                                                                                        
   (	"CONFIG_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                   
	"NAME" VARCHAR2(500) NOT NULL ENABLE,                                                                                                                                                                 
	"IS_SUPPORT_IMAGE" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                             
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"CREATION_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                 
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                            
	"UPDATED_DATE" DATE,                                                                                                                                                                                  
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                         
	"IS_SAVE" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                      
	 PRIMARY KEY ("CONFIG_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                  
   ) ;                                                                                                                                                                                                 

